const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();

const SANDBOX_ROOT = path.resolve('sandbox');
fs.mkdirSync(SANDBOX_ROOT, { recursive: true });
fs.writeFileSync(path.join(SANDBOX_ROOT, 'notas.txt'), 'Este arquivo esta dentro do sandbox permitido.');

function resolveSafePath(relative = '.') {
  const rel = String(relative || '.').replace(/^\/+/, '');
  const abs = path.resolve(SANDBOX_ROOT, rel);
  const root = path.resolve(SANDBOX_ROOT);
  if (abs !== root && !abs.startsWith(root + path.sep)) {
    throw new Error('Caminho fora da area permitida: ' + relative);
  }
  return abs;
}

app.get('/api/arquivo', (req, res) => {
  try {
    const abs = resolveSafePath(req.query.caminho || 'notas.txt');
    const conteudo = fs.readFileSync(abs, 'utf8');
    res.json({ ok: true, caminho: abs, conteudo });
  } catch (err) {
    res.status(400).json({ ok: false, erro: err.message });
  }
});

