const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

const sessoes = new Map();

function emitirSessao(email) {
  const access_token = 'local.' + crypto.randomBytes(16).toString('hex');
  const expires_at = Math.floor(Date.now() / 1000) + 60 * 60 * 24;
  const sessao = { access_token, email, expires_at };
  sessoes.set(access_token, sessao);
  return sessao;
}

function lerBearer(req) {
  const header = req.headers.authorization || '';
  return header.startsWith('Bearer ') ? header.slice(7) : '';
}

app.post('/api/login', (req, res) => {
  const email = String(req.body?.email || 'convidado@exemplo.com').trim();
  res.json({ session: emitirSessao(email) });
});

app.get('/api/me', (req, res) => {
  const token = lerBearer(req);
  const sessao = sessoes.get(token);
  if (!sessao) return res.status(401).json({ erro: 'Sessao invalida ou ausente.' });
  res.json({ email: sessao.email, expira_em: new Date(sessao.expires_at * 1000).toISOString() });
});

