const express = require('express');
const app = express();
app.use(express.json());

const ouvintes = new Set();

function emitirEvento(texto) {
  const corpo = { texto: String(texto || ''), hora: new Date().toLocaleTimeString('pt-BR') };
  const linha = 'data: ' + JSON.stringify(corpo) + '\n\n';
  for (const res of ouvintes) {
    try {
      res.write(linha);
    } catch {
      // cliente ja desconectou, ignora
    }
  }
}

app.get('/api/eventos', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
  });
  res.write('data: ' + JSON.stringify({ texto: 'Conectado ao stream.', hora: new Date().toLocaleTimeString('pt-BR') }) + '\n\n');
  ouvintes.add(res);
  req.on('close', () => ouvintes.delete(res));
});

app.post('/api/emitir', (req, res) => {
  emitirEvento(req.body?.texto || 'Evento manual disparado.');
  res.json({ ok: true });
});

