const TOKEN_ADMIN_DEMO = 'segredo123';

function enviarErro(res, err) {
  const status = err.status || 400;
  res.status(status).json({ erro: err.message || String(err) });
}

function exigirTokenAdmin(req, res, next) {
  const token = req.headers['x-admin-token'] || '';
  if (token !== TOKEN_ADMIN_DEMO) {
    const err = new Error('Token administrativo invalido.');
    err.status = 401;
    return enviarErro(res, err);
  }
  next();
}

