const express = require('express');
const crypto = require('crypto');
const fs = require('fs');
const app = express();
app.use(express.json());

const DB_FILE = 'propostas.json';

function carregarTudo() {
  try {
    return JSON.parse(fs.readFileSync(DB_FILE, 'utf8'));
  } catch {
    return [];
  }
}

function salvarTudo(linhas) {
  fs.writeFileSync(DB_FILE, JSON.stringify(linhas, null, 2));
}

app.get('/api/propostas', (req, res) => {
  res.json(carregarTudo());
});

app.post('/api/propostas', (req, res) => {
  const linhas = carregarTudo();
  const proposta = {
    id: 'p_' + crypto.randomUUID().slice(0, 8),
    titulo: String(req.body?.titulo || '').slice(0, 200),
    status: 'pending',
    criado_em: new Date().toISOString(),
  };
  linhas.push(proposta);
  salvarTudo(linhas);
  res.status(201).json(proposta);
});

function resolverProposta(id, novoStatus, res) {
  const linhas = carregarTudo();
  const i = linhas.findIndex((p) => p.id === id);
  if (i < 0) return res.status(404).json({ erro: 'Proposta nao encontrada.' });
  if (linhas[i].status !== 'pending') {
    return res.status(400).json({ erro: 'Proposta ja foi resolvida (status atual: ' + linhas[i].status + ').' });
  }
  linhas[i] = { ...linhas[i], status: novoStatus, resolvido_em: new Date().toISOString() };
  salvarTudo(linhas);
  res.json(linhas[i]);
}

app.post('/api/propostas/:id/aprovar', (req, res) => resolverProposta(req.params.id, 'approved', res));
